import type { TrafficStatsResponse } from "../types/api";

// The API speaks in codes (MONDAY, LOCAL, SUNNY...). These functions only change what the screen shows.

const weekdayLabels: Record<string, string> = {
  MONDAY: "Seg",
  TUESDAY: "Ter",
  WEDNESDAY: "Qua",
  THURSDAY: "Qui",
  FRIDAY: "Sex",
  SATURDAY: "Sáb",
  SUNDAY: "Dom"
};

const roadTypeLabels: Record<string, string> = {
  LOCAL: "Via local",
  ARTERIAL: "Via arterial",
  HIGHWAY: "Via expressa",
  UNKNOWN: "Não informado"
};

// The weather codes generated by the simulation. Weather typed by a person is free text and is shown as it was.
const weatherLabels: Record<string, string> = {
  SUNNY: "Ensolarado",
  RAIN: "Chuva",
  CLOUDY: "Nublado"
};

const trafficLevelLabels: Record<string, string> = {
  LOW: "Baixo",
  MEDIUM: "Médio",
  HIGH: "Alto"
};

/** "ESTRADA_DE_TERRA" becomes "Estrada De Terra": readable text for codes the lists above do not know. */
function titleCase(value: string) {
  return value.replace(/_/g, " ").toLowerCase().replace(/(^|\s)\S/g, (letter) => letter.toUpperCase());
}

export function weekdayLabel(code: string) {
  return weekdayLabels[code.toUpperCase()] ?? titleCase(code);
}

export function roadTypeLabel(code: string) {
  return roadTypeLabels[code.toUpperCase()] ?? titleCase(code);
}

export function weatherLabel(value: string) {
  return weatherLabels[value.toUpperCase()] ?? value;
}

export function trafficLevelLabel(level: string) {
  return trafficLevelLabels[level.toUpperCase()] ?? titleCase(level);
}

/**
 * The hour with the highest volume, as "18h". The backend returns the 24 hours, with zero where there are no
 * records, so a list that is all zeros means there is no data to point at.
 */
export function peakHourLabel(stats: TrafficStatsResponse) {
  let peakIndex = -1;
  stats.values.forEach((value, index) => {
    if (value > 0 && (peakIndex < 0 || value > (stats.values[peakIndex] ?? 0))) {
      peakIndex = index;
    }
  });

  const label = peakIndex < 0 ? undefined : stats.labels[peakIndex];
  return label === undefined ? "Sem dados" : `${Number(label)}h`;
}
